<?php
declare(strict_types=1);
function payroll_schema(): PDO {$db=team_db();$db->exec("CREATE TABLE IF NOT EXISTS work_schedule(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,date TEXT NOT NULL,start_min INTEGER NOT NULL,end_min INTEGER NOT NULL,lunch INTEGER NOT NULL,kind TEXT NOT NULL,note TEXT NOT NULL,actor TEXT NOT NULL,cancelled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS work_schedule_date ON work_schedule(user_id,date);CREATE TABLE IF NOT EXISTS payroll_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,month TEXT NOT NULL,snapshot TEXT NOT NULL,note TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL)");return $db;}
function payroll_minute($v): int {if(!is_string($v)||!preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D',$v))throw new RuntimeException('Giờ không hợp lệ.',400);return (int)substr($v,0,2)*60+(int)substr($v,3,2);}
function payroll_schedule(array $data): void {
 $u=team_identity();$db=payroll_schema();$id=$data['id']??0;$uid=$u['owner']?(int)($data['user_id']??0):$u['id'];$date=$data['date']??'';if(!is_int($id)||!is_string($date))throw new RuntimeException('Lịch không hợp lệ.',400);$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date,new DateTimeZone('Asia/Ho_Chi_Minh'));if(!$d||$d->format('Y-m-d')!==$date||$uid<1)throw new RuntimeException('Cần ngày và nhân viên hợp lệ.',400);$q=$db->prepare('SELECT 1 FROM staff WHERE id=?');$q->execute([$uid]);if(!$q->fetchColumn())throw new RuntimeException('Không tìm thấy nhân viên.',404);
 $start=payroll_minute($data['start']??'');$end=payroll_minute($data['end']??'');$lunch=$data['lunch']??11;$kind=$data['kind']??'';$note=trim((string)($data['note']??''));$cancel=$data['cancel']??false;if(!in_array($kind,['work','leave'],true)||!in_array($lunch,[11,12],true)||$start<420||$end>1410||$end<=$start||mb_strlen($note)>1000||!is_bool($cancel))throw new RuntimeException('Lịch trong khoảng 07:00–23:30; chọn làm việc hoặc đăng ký nghỉ.',400);
 $old=null;if($id){$q=$db->prepare('SELECT * FROM work_schedule WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old||(!$u['owner']&&(int)$old['user_id']!==$u['id']))throw new RuntimeException('Không được sửa lịch của người khác.',403);}
 $stamp=$d->getTimestamp()+$start*60;if(!$u['owner']&&($stamp<=time()||($old&&(new DateTimeImmutable($old['date'],new DateTimeZone('Asia/Ho_Chi_Minh')))->getTimestamp()+(int)$old['start_min']*60<=time())))throw new RuntimeException('Chỉ đăng ký, sửa hoặc hủy trước giờ bắt đầu. Cần quản trị viên điều chỉnh lịch quá giờ.',403);
 if($u['owner']&&($stamp<=time()||$old)&&mb_strlen($note)<3)throw new RuntimeException('Cần lý do khi quản trị viên sửa lịch hoặc bổ sung lịch quá giờ.',400);
 $q=$db->prepare('SELECT id FROM work_schedule WHERE user_id=? AND date=? AND cancelled=0 AND id<>? AND start_min<? AND end_min>?');$q->execute([$uid,$date,$id,$end,$start]);if(!$cancel&&$q->fetch())throw new RuntimeException('Lịch bị trùng với một khoảng đã đăng ký.',409);
 $db->beginTransaction();try{if($old){$db->prepare('UPDATE work_schedule SET cancelled=1 WHERE id=?')->execute([$id]);}if(!$cancel)$db->prepare('INSERT INTO work_schedule(user_id,date,start_min,end_min,lunch,kind,note,actor,created_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$uid,$date,$start,$end,$lunch,$kind,$note,$u['username'],gmdate('c')]);people_audit('schedule','Lịch #'.$uid.' · '.$date,['before'=>$old,'after'=>$cancel?null:['date'=>$date,'start'=>$start,'end'=>$end,'lunch'=>$lunch,'kind'=>$kind,'note'=>$note]]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}
}
function payroll_schedule_list(int $uid,string $month): array {people_month($month);$db=payroll_schema();$q=$db->prepare('SELECT * FROM work_schedule WHERE user_id=? AND date LIKE ? AND cancelled=0 ORDER BY date,start_min');$q->execute([$uid,$month.'-%']);return $q->fetchAll();}
function payroll_policy(): array {return people_setting('payroll_policy',['rounding'=>null,'idle_minutes'=>null,'late_reset'=>null,'leave_counts'=>null]);}
function payroll_policy_save(array $data): void {people_require_owner();$p=$data['policy']??[];if(!is_array($p)||!in_array($p['rounding']??null,['half_floor','half_grace5'],true)||!is_int($p['idle_minutes']??null)||$p['idle_minutes']<1||$p['idle_minutes']>120||!in_array($p['late_reset']??null,['month'],true)||!is_bool($p['leave_counts']??null))throw new RuntimeException('Cần xác nhận đủ quy tắc tính lương.',400);$before=payroll_policy();people_set('payroll_policy',array_intersect_key($p,array_flip(['rounding','idle_minutes','late_reset','leave_counts'])));people_audit('payroll_policy','Quy tắc lương',['before'=>$before,'after'=>$p]);}
function payroll_ready(array $p): bool {foreach(['rounding','idle_minutes','late_reset','full_day','leave_counts'] as $key)if(!array_key_exists($key,$p)||$p[$key]===null)return false;return true;}
function payroll_union(array $ranges): array {usort($ranges,fn($a,$b)=>$a[0]<=>$b[0]);$out=[];foreach($ranges as [$a,$b]){if($b<=$a)continue;$i=count($out)-1;if($i>=0&&$a<=$out[$i][1])$out[$i][1]=max($out[$i][1],$b);else $out[]=[$a,$b];}return $out;}
function payroll_overlap(array $ranges,int $a,int $b): int {$sum=0;foreach($ranges as [$s,$e])$sum+=max(0,min($e,$b)-max($s,$a));return $sum;}
function payroll_hours(int $seconds,string $mode): float {return intdiv($seconds+($mode==='half_grace5'?300:0),1800)/2;}
function payroll_compute(array $sessions,array $schedule,string $month,array $policy): array {
 if(!payroll_ready($policy))throw new RuntimeException('Cần xác nhận đủ quy tắc lương trước khi tính.',409);[$from,$to]=people_month($month);$ranges=[];$pending=0;foreach($sessions as $s){if(!(int)$s['effective_approved']||$s['effective_end']===null){$pending++;continue;}$ranges[]=[max($from,(int)$s['effective_start']),min($to,(int)$s['effective_end'])];}$ranges=payroll_union($ranges);$byDate=[];foreach($schedule as $s)$byDate[$s['date']][]=$s;
 $days=[];$base=0;$meal=0;$late=0;$absent=0;$eligibleDay=false;$eligibleEvening=false;$hasSchedule=count($schedule)>0;
 $start=new DateTimeImmutable($month.'-01',new DateTimeZone('Asia/Ho_Chi_Minh'));for($day=$start;$day->getTimestamp()<$to;$day=$day->modify('+1 day')){$stamp=$day->getTimestamp();$date=$day->format('Y-m-d');$plans=$byDate[$date]??[];$lunch=(int)($plans[0]['lunch']??11);$windows=['morning'=>[$stamp+420*60,$stamp+$lunch*3600],'afternoon'=>[$stamp+($lunch+1)*3600,$stamp+1110*60],'evening'=>[$stamp+1110*60,$stamp+1320*60],'night'=>[$stamp+1320*60,$stamp+1410*60]];
 $daySec=payroll_overlap($ranges,$stamp+420*60,$stamp+1110*60);$eveningSec=payroll_overlap($ranges,...$windows['evening']);$nightSec=payroll_overlap($ranges,...$windows['night']);$h=['day'=>payroll_hours($daySec,$policy['rounding']),'evening'=>payroll_hours($eveningSec,$policy['rounding']),'night'=>payroll_hours($nightSec,$policy['rounding'])];$wage=$h['day']*25000+$h['evening']*27000+$h['night']*50000;$base+=$wage;
 $dailyLate=0;$dailyAbsent=0;$expected=[];foreach($plans as $plan){$a=$stamp+(int)$plan['start_min']*60;$b=$stamp+(int)$plan['end_min']*60;if($a>time())continue;
 if($plan['kind']==='work'){$first=null;foreach($ranges as [$x,$y])if($y>$a&&$x<$b){$first=max($x,$a);break;}if($first!==null&&$first>$a+300)$dailyLate++;}
 foreach($windows as $shift=>[$x,$y]){if(min($b,$y)<=max($a,$x))continue;if($shift==='morning'||$shift==='afternoon')$eligibleDay=true;if($shift==='evening')$eligibleEvening=true;$key=$shift;if(isset($expected[$key]))continue;$expected[$key]=true;if($plan['kind']==='leave'){if($policy['leave_counts'])$dailyAbsent++;}elseif($b<=time()&&payroll_overlap($ranges,max($a,$x),min($b,$y))===0)$dailyAbsent++;}}
 $morning=payroll_overlap($ranges,...$windows['morning']);$afternoon=payroll_overlap($ranges,...$windows['afternoon']);$fullDay=$daySec>=28800;$fullEvening=$h['evening']>=3.5;$fullNight=$h['night']>=1.5;$food=$fullDay?($fullEvening&&$fullNight?40000:20000):0;$meal+=$food;$late+=$dailyLate;$absent+=$dailyAbsent;
 if($daySec||$eveningSec||$nightSec||$plans)$days[]=['date'=>$date,'seconds'=>['day'=>$daySec,'evening'=>$eveningSec,'night'=>$nightSec],'hours'=>$h,'base'=>$wage,'meal'=>$food,'late'=>$dailyLate,'absent'=>$dailyAbsent,'fullDay'=>$fullDay];}
 $fine=max(0,$late-3)*10000;$monthComplete=$to<=time();$bonus=$hasSchedule&&$base>0&&$absent<=3?($eligibleDay?350000:($eligibleEvening?200000:0)):0;
 return ['days'=>$days,'hours'=>array_reduce($days,fn($v,$d)=>['day'=>$v['day']+$d['hours']['day'],'evening'=>$v['evening']+$d['hours']['evening'],'night'=>$v['night']+$d['hours']['night']],['day'=>0,'evening'=>0,'night'=>0]),'base'=>$base,'meal'=>$meal,'late'=>$late,'absent'=>$absent,'warnings'=>min(3,$late),'fine'=>$fine,'bonus'=>$bonus,'total'=>$base+$meal+$bonus-$fine,'pending'=>$pending,'scheduleRegistered'=>$hasSchedule,'monthComplete'=>$monthComplete,'policy'=>$policy];
}
